import './App.css';
import CodeBox from './components/code-box';
import QuestionBubble from './components/question-bubble';

function App() {
  return (
    <div className="App">
      <div className='content-line'>
        <div className='logo-line'>
          <img src="/assets/logo.jpg" alt="Logo" className="logo-image" />
        </div>
      </div>

      <div className='content-wrapper'>
        <div className='content-line'>
          <div className='content-column'>
            <QuestionBubble/>
          </div>
          <div className='content-column'>
            <CodeBox code={`
class MyClass:
    def __init__(self, name):
        self.name = name

    def greet(self):
        return f"Hello, {self.name}!"

obj = MyClass("Alice")
print(obj.greet())
  `}/>
          </div>
        </div>
      </div>
      <div className='name-line'>
        Project created by Lucas Marques Felix
      </div>
    </div>
  );
}

export default App;
